python3 << 'PYSCRIPT'
import json
import uuid
from datetime import datetime, timedelta

# Generate node IDs
trigger_id = str(uuid.uuid4())
action_id = str(uuid.uuid4())

# Build quest document for inactive creation
quest_body = {
    "name": "Defeat Dragon for Fire Sword",
    "type": "liveops",
    "status": "inactive",
    "created_by": "AI Toolkit",
    "nodes": [
        {
            "id": trigger_id,
            "name": "Dragon defeated",
            "type": "trigger",
            "subtype": "dynamic_event",
            "parameters": {
                "event_name": "dragon_defeated"
            }
        },
        {
            "id": action_id,
            "name": "Issue Fire Sword",
            "type": "action",
            "subtype": "issue_reward",
            "parameters": {
                "type": "web3_item",
                "purpose": "quest_completion",
                "body": {
                    "project": "316665",
                    "item_sku": "qp_fire_sword_1",
                    "quantity": 1
                }
            }
        }
    ],
    "connections": {
        trigger_id: [
            {
                "nodeId": action_id
            }
        ]
    },
    "activation_limits": [
        {
            "type": "per_user",
            "count": 1
        }
    ]
}

print(json.dumps(quest_body, indent=2))
PYSCRIPT

